var t=`0222-cozido-a-portuguesa`;var a=`world-0222`;var o=`PT`;var n=`southern-europe`;var s=4;var r=117;var g={en:`Cozido à Portuguesa`,ua:`Козіду по-португальськи`};var l={en:`A traditional Portugal dish made with beef chuck, pork shoulder, smoked ham, bay leaf. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Португалія. Основні інгредієнти: яловича лопатка, свиняча лопатка, копчена шинка, лавровий лист. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var m=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 80 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 80 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:80,i:[[`beef-chuck`,370,`g`],[`pork-shoulder`,340,`g`],[`smoked-ham`,160,`g`],[`water`,1700,`ml`],[`bay-leaf`,2,`leaf`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 35 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 35 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:35,i:[[`potato`,400,`g`],[`carrot`,230,`g`],[`white-cabbage`,300,`g`],[`chorizo-cured`,180,`g`],[`blood-sausage`,180,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`table-salt`,null,`to_taste`],[`extra-virgin-olive-oil`,20,`ml`]]}];var u={slug:t,id:a,country:`PT`,region:n,servings:4,minutes:117,title:g,text:l,steps:m};export{o as country,u as default,a as id,r as minutes,n as region,s as servings,t as slug,m as steps,l as text,g as title};